ControlPropertyState.AutoRuleBindingString:
If(
    IsBlank(varProjectId),

    Notify("Please select a project first.", NotificationType.Warning),

    Set(varGlobalLoading, true);
    Set(varGlobalLoadingMsg, "Refreshing dashboard...");
    Set(varGlobalLoadingSubMsg, "Updating operational data");
    
    Set(varGlobalLoadingScope, "HOME");

    Set(varHomeLoading, true);
    Set(varProjectSwitching, false);

    Set(varGlobalLoadAction, "LOAD_HOME");
    Set(varGlobalLoadPending, true)
)

UpdateContext({locForcePaint: !locForcePaint});


If(
    !IsBlank(Self.Selected.ProjectId),

    Set(varProjectSwitching, true);
    Set(varPHR_IsLoading, true);
    Set(varLoadingMsg, "Changing project...");

    // --------------------------------------------------
    // 1) Set selected project
    // --------------------------------------------------
     Set(
        varSelectedProject,
        LookUp(
            colEnabledProjectsUI,
            Value(ProjectId) = Value(Self.Selected.ProjectId)
        )
    );

    Clear(colPHR_Subsystems);
    Clear(colPHR_Metrics);
    Clear(colPHR_Headers);
    Clear(colPHR_HeaderL4_Active);
    Clear(colPHR_HeaderL3_Active);
    Clear(colPHR_HeaderL2_Active);
    Clear(colPHR_HeaderL1_Active);
    Clear(colPHR_RowCells_Active);

    Set(varPHR_Page, 1);
    Set(varPHR_PageSize, 50);
    Set(varPHR_TotalCount, 0);
    Set(varPHR_SelectedL1NodeId, "");
    Set(varPHR_SelectedL1Label, "");

    Set(varProjectId, Value(varSelectedProject.ProjectId));
    Set(varProjectCode, Text(varSelectedProject.ProjectCode));
    Set(varProjectName, Text(varSelectedProject.ProjectName));
    Set(varProjectDescription, Text(varSelectedProject.ProjectDescription));
    Set(varAppView, "Home");
    Set(varHomeViewMode, "DASHBOARD");
    Set(varProjectLoaded, true);

If(
    !IsBlank(varProjectId),
    Select(btnHome_LoadHive)
);
    Set(varProjectLoaded, true);

    // --------------------------------------------------
    // 2) Reset global UI state
    // --------------------------------------------------
    Set(varBriefingEmailVisible, false);
    Set(varShowDetailDrawer, false);
    Set(varOps_DrawerOpen, false);
    Set(varScopeModalOpen, false);
    Set(varNodeModalOpen, false);

    // --------------------------------------------------
    // 3) Reset filters
    // --------------------------------------------------
    Set(varFilter_Subsystem, "");
    Set(varOps_FilterSubsystem, "");
    Set(varOps_FilterStatus, "");
    Set(varOps_FilterOwner, "");
    Set(varOps_FilterOnlyOverdue, false);
    Set(varOps_FilterOnlyAttention, false);
    Set(varOps_QuickFilter, "ALL");

    // --------------------------------------------------
    // 4) Reset PHR paging and dimensions
    // --------------------------------------------------
    Set(varPHR_Page, 1);
    Set(varPHR_PageSize, 50);
    Set(varPHR_TotalCount, 0);

    Set(varPHR_ColW, 66);


    Set(varPHR_SubsysW, 180);
    Set(varPHR_ActionsW, 90);

    Set(varPHR_HeaderH1, 28);
    Set(varPHR_HeaderH2, 28);
    Set(varPHR_HeaderH3, 28);
    Set(varPHR_HeaderH4, 32);
    Set(varPHR_RowH, 52);

    Set(varPHR_SelectedL1NodeId, "");
    Set(varPHR_SelectedL1Label, "");

    Set(varPHR_DataColsWidth, 0);
    Set(varPHR_TotalGridWidth, 0);
    Set(varPHR_DataColsWidth_Active, 0);
    Set(varPHR_TotalGridWidth_Active, 0);

    // --------------------------------------------------
    // 5) Clear project-dependent collections
    // --------------------------------------------------
    Clear(colOpsCells);
    Clear(colTasks);
    Clear(colPunches);
    Clear(colComments);


    Clear(colPHR_Subsystems);
    Clear(colPHR_Metrics);
    Clear(colPHR_Headers);
    Clear(colPHR_HeaderL4);
    Clear(colPHR_HeaderL4Indexed);
    Clear(colPHR_HeaderL3Base);
    Clear(colPHR_HeaderL2Base);
    Clear(colPHR_HeaderL1Base);
    Clear(colPHR_TabsL1);
    Clear(colPHR_RowCells);
    Clear(colPHR_HeaderL4_Active);
    Clear(colPHR_HeaderL3_Active);
    Clear(colPHR_HeaderL2_Active);
    Clear(colPHR_HeaderL1_Active);
    Clear(colPHR_RowCells_Active);

    Clear(colBriefingEvents);
    Clear(colBriefingKpis);

    // --------------------------------------------------
    // 6) Reset dashboard / briefing
    // --------------------------------------------------

    Set(varHomeDashboardLoaded, false);
    Set(varBriefingNotes, Blank());
    Set(varBriefingEmailSubject, Blank());
    Set(varBriefingEmailBody, Blank());

    // --------------------------------------------------
    // 7) Keep user in current view, but load only if needed
    // --------------------------------------------------
    If(
        varAppView = "Home",
        Set(varHomeViewMode, "DASHBOARD");
  
    );


    Reset(cmbHome_ProjectSelector);
    
    Set(varProjectSwitching, false);
    Set(varPHR_IsLoading, false);
    Set(varLoadingMsg, "");


    
)
